package yaml

import (
	"bufio"
	"bytes"
	"fmt"
	"io"
	"strconv"
	"strings"
)

type Kind uint32
type Style uint32

const (
	DocumentNode Kind = 1 + iota
	SequenceNode
	MappingNode
	ScalarNode
)

const (
	FlowStyle Style = 1 << iota
)

type Node struct {
	Kind    Kind
	Style   Style
	Tag     string
	Value   string
	Content []*Node
}

type Decoder struct {
	data   []byte
	docs   []*Node
	err    error
	parsed bool
	index  int
}

func NewDecoder(r io.Reader) *Decoder {
	data, err := io.ReadAll(r)
	return &Decoder{data: data, err: err}
}

func (d *Decoder) Decode(v any) error {
	if d.err != nil {
		return d.err
	}
	if !d.parsed {
		d.docs, d.err = parseDocuments(d.data)
		d.parsed = true
		if d.err != nil {
			return d.err
		}
	}
	if d.index >= len(d.docs) {
		return io.EOF
	}
	target, ok := v.(*Node)
	if !ok {
		return fmt.Errorf("yaml: Decode expects *Node")
	}
	*target = Node{Kind: DocumentNode}
	if d.docs[d.index] != nil {
		target.Content = []*Node{cloneNode(d.docs[d.index])}
	}
	d.index++
	return nil
}

type Encoder struct {
	w      io.Writer
	indent int
}

func NewEncoder(w io.Writer) *Encoder {
	return &Encoder{w: w, indent: 2}
}

func (e *Encoder) SetIndent(n int) {
	e.indent = n
}

func (e *Encoder) Encode(v any) error {
	var node *Node
	switch t := v.(type) {
	case *Node:
		node = t
	case Node:
		node = &t
	default:
		return fmt.Errorf("yaml: Encode expects Node")
	}
	if node.Kind == DocumentNode {
		if len(node.Content) == 0 || node.Content[0] == nil {
			_, err := io.WriteString(e.w, "\n")
			return err
		}
		_, err := io.WriteString(e.w, renderYAML(node.Content[0], e.indent, 0))
		return err
	}
	_, err := io.WriteString(e.w, renderYAML(node, e.indent, 0))
	return err
}

func (e *Encoder) Close() error {
	return nil
}

func parseDocuments(data []byte) ([]*Node, error) {
	if len(data) == 0 {
		return []*Node{nil}, nil
	}
	scanner := bufio.NewScanner(bytes.NewReader(data))
	docs := make([][]string, 1)
	for scanner.Scan() {
		line := strings.TrimRight(scanner.Text(), "\r")
		if strings.TrimSpace(line) == "---" {
			docs = append(docs, nil)
			continue
		}
		docs[len(docs)-1] = append(docs[len(docs)-1], line)
	}
	if err := scanner.Err(); err != nil {
		return nil, err
	}
	out := make([]*Node, 0, len(docs))
	for _, docLines := range docs {
		node, err := parseDocument(docLines)
		if err != nil {
			return nil, err
		}
		out = append(out, node)
	}
	return out, nil
}

type parsedLine struct {
	indent int
	text   string
}

func parseDocument(lines []string) (*Node, error) {
	parsed := make([]parsedLine, 0, len(lines))
	for _, raw := range lines {
		if strings.TrimSpace(raw) == "" {
			continue
		}
		trimmed := strings.TrimLeft(raw, " ")
		if strings.HasPrefix(trimmed, "#") {
			continue
		}
		indent := len(raw) - len(trimmed)
		parsed = append(parsed, parsedLine{indent: indent, text: trimmed})
	}
	if len(parsed) == 0 {
		return nil, nil
	}
	index := 0
	return parseBlock(parsed, &index, parsed[0].indent)
}

func parseBlock(lines []parsedLine, index *int, indent int) (*Node, error) {
	if *index >= len(lines) {
		return nil, nil
	}
	line := lines[*index]
	if line.indent < indent {
		return nil, nil
	}
	if line.indent > indent {
		return nil, fmt.Errorf("yaml: unexpected indentation")
	}
	if strings.HasPrefix(line.text, "- ") || line.text == "-" {
		return parseSequence(lines, index, indent)
	}
	if _, _, ok := splitKeyValue(line.text); ok {
		return parseMapping(lines, index, indent)
	}
	*index++
	return parseInlineValue(line.text)
}

func parseSequence(lines []parsedLine, index *int, indent int) (*Node, error) {
	seq := &Node{Kind: SequenceNode, Tag: "!!seq"}
	for *index < len(lines) {
		line := lines[*index]
		if line.indent < indent {
			break
		}
		if line.indent != indent || (!strings.HasPrefix(line.text, "- ") && line.text != "-") {
			break
		}
		rest := strings.TrimSpace(strings.TrimPrefix(line.text, "-"))
		*index++
		switch {
		case rest == "":
			child, err := parseBlock(lines, index, indent+2)
			if err != nil {
				return nil, err
			}
			if child == nil {
				child = newNullNode()
			}
			seq.Content = append(seq.Content, child)
		case looksLikeKeyValue(rest):
			child, err := parseMapFromFirst(rest, lines, index, indent+2)
			if err != nil {
				return nil, err
			}
			seq.Content = append(seq.Content, child)
		default:
			child, err := parseInlineValue(rest)
			if err != nil {
				return nil, err
			}
			seq.Content = append(seq.Content, child)
		}
	}
	return seq, nil
}

func parseMapping(lines []parsedLine, index *int, indent int) (*Node, error) {
	node := &Node{Kind: MappingNode, Tag: "!!map"}
	for *index < len(lines) {
		line := lines[*index]
		if line.indent < indent {
			break
		}
		if line.indent != indent {
			break
		}
		if strings.HasPrefix(line.text, "- ") || line.text == "-" {
			break
		}
		key, rest, ok := splitKeyValue(line.text)
		if !ok {
			break
		}
		*index++
		var value *Node
		var err error
		if rest == "" {
			value, err = parseBlock(lines, index, indent+2)
			if err != nil {
				return nil, err
			}
			if value == nil {
				value = newNullNode()
			}
		} else {
			value, err = parseInlineValue(rest)
			if err != nil {
				return nil, err
			}
		}
		node.Content = append(node.Content, &Node{Kind: ScalarNode, Tag: "!!str", Value: key}, value)
	}
	return node, nil
}

func parseMapFromFirst(first string, lines []parsedLine, index *int, indent int) (*Node, error) {
	node := &Node{Kind: MappingNode, Tag: "!!map"}
	if err := appendMapEntry(node, first, lines, index, indent, false); err != nil {
		return nil, err
	}
	for *index < len(lines) {
		line := lines[*index]
		if line.indent < indent {
			break
		}
		if line.indent != indent {
			break
		}
		if strings.HasPrefix(line.text, "- ") || line.text == "-" {
			break
		}
		if err := appendMapEntry(node, line.text, lines, index, indent, true); err != nil {
			return nil, err
		}
	}
	return node, nil
}

func appendMapEntry(node *Node, text string, lines []parsedLine, index *int, indent int, consumeLine bool) error {
	key, rest, ok := splitKeyValue(text)
	if !ok {
		return fmt.Errorf("yaml: invalid mapping entry")
	}
	if consumeLine {
		*index++
	}
	var value *Node
	var err error
	if rest == "" {
		value, err = parseBlock(lines, index, indent+2)
		if err != nil {
			return err
		}
		if value == nil {
			value = newNullNode()
		}
	} else {
		value, err = parseInlineValue(rest)
		if err != nil {
			return err
		}
	}
	node.Content = append(node.Content, &Node{Kind: ScalarNode, Tag: "!!str", Value: key}, value)
	return nil
}

func splitKeyValue(text string) (string, string, bool) {
	depth := 0
	inQuote := false
	escaped := false
	for i := 0; i < len(text); i++ {
		ch := text[i]
		if inQuote {
			if escaped {
				escaped = false
				continue
			}
			if ch == '\\' {
				escaped = true
				continue
			}
			if ch == '"' {
				inQuote = false
			}
			continue
		}
		switch ch {
		case '"':
			inQuote = true
		case '{', '[':
			depth++
		case '}', ']':
			if depth > 0 {
				depth--
			}
		case ':':
			if depth == 0 {
				key := strings.TrimSpace(text[:i])
				rest := strings.TrimSpace(text[i+1:])
				if key == "" {
					return "", "", false
				}
				return key, rest, true
			}
		}
	}
	return "", "", false
}

func looksLikeKeyValue(text string) bool {
	_, _, ok := splitKeyValue(text)
	return ok
}

func parseInlineValue(text string) (*Node, error) {
	text = strings.TrimSpace(text)
	if text == "" {
		return newNullNode(), nil
	}
	switch {
	case strings.HasPrefix(text, "{"), strings.HasPrefix(text, "["):
		parser := flowParser{src: text}
		node, err := parser.parseValue()
		if err != nil {
			return nil, err
		}
		parser.skipSpaces()
		if !parser.eof() {
			return nil, fmt.Errorf("yaml: trailing flow content")
		}
		return node, nil
	case strings.HasPrefix(text, "\"") && strings.HasSuffix(text, "\""):
		value, err := strconv.Unquote(text)
		if err != nil {
			return nil, err
		}
		return &Node{Kind: ScalarNode, Tag: "!!str", Value: value}, nil
	case strings.HasPrefix(text, "'") && strings.HasSuffix(text, "'"):
		return &Node{Kind: ScalarNode, Tag: "!!str", Value: text[1 : len(text)-1]}, nil
	case text == "null" || text == "~":
		return newNullNode(), nil
	case text == "true":
		return &Node{Kind: ScalarNode, Tag: "!!bool", Value: "true"}, nil
	case text == "false":
		return &Node{Kind: ScalarNode, Tag: "!!bool", Value: "false"}, nil
	case isNumber(text):
		tag := "!!int"
		if strings.ContainsAny(text, ".eE") {
			tag = "!!float"
		}
		return &Node{Kind: ScalarNode, Tag: tag, Value: text}, nil
	default:
		return &Node{Kind: ScalarNode, Tag: "!!str", Value: text}, nil
	}
}

type flowParser struct {
	src string
	pos int
}

func (p *flowParser) eof() bool {
	return p.pos >= len(p.src)
}

func (p *flowParser) skipSpaces() {
	for !p.eof() && strings.ContainsRune(" \t\r\n", rune(p.src[p.pos])) {
		p.pos++
	}
}

func (p *flowParser) parseValue() (*Node, error) {
	p.skipSpaces()
	if p.eof() {
		return newNullNode(), nil
	}
	switch p.src[p.pos] {
	case '{':
		return p.parseMap()
	case '[':
		return p.parseSeq()
	case '"':
		return p.parseQuoted()
	default:
		token := p.readPlainToken()
		return parseInlineValue(token)
	}
}

func (p *flowParser) parseMap() (*Node, error) {
	p.pos++
	node := &Node{Kind: MappingNode, Tag: "!!map", Style: FlowStyle}
	for {
		p.skipSpaces()
		if p.eof() {
			return nil, fmt.Errorf("yaml: unterminated flow map")
		}
		if p.src[p.pos] == '}' {
			p.pos++
			return node, nil
		}
		keyToken := p.readFlowKey()
		keyNode, err := parseInlineValue(strings.TrimSpace(keyToken))
		if err != nil {
			return nil, err
		}
		p.skipSpaces()
		if p.eof() || p.src[p.pos] != ':' {
			return nil, fmt.Errorf("yaml: invalid flow map")
		}
		p.pos++
		value, err := p.parseValue()
		if err != nil {
			return nil, err
		}
		node.Content = append(node.Content, &Node{Kind: ScalarNode, Tag: "!!str", Value: keyNode.Value}, value)
		p.skipSpaces()
		if p.eof() {
			return nil, fmt.Errorf("yaml: unterminated flow map")
		}
		if p.src[p.pos] == ',' {
			p.pos++
			continue
		}
		if p.src[p.pos] == '}' {
			p.pos++
			return node, nil
		}
		return nil, fmt.Errorf("yaml: invalid flow map separator")
	}
}

func (p *flowParser) parseSeq() (*Node, error) {
	p.pos++
	node := &Node{Kind: SequenceNode, Tag: "!!seq", Style: FlowStyle}
	for {
		p.skipSpaces()
		if p.eof() {
			return nil, fmt.Errorf("yaml: unterminated flow sequence")
		}
		if p.src[p.pos] == ']' {
			p.pos++
			return node, nil
		}
		value, err := p.parseValue()
		if err != nil {
			return nil, err
		}
		node.Content = append(node.Content, value)
		p.skipSpaces()
		if p.eof() {
			return nil, fmt.Errorf("yaml: unterminated flow sequence")
		}
		if p.src[p.pos] == ',' {
			p.pos++
			continue
		}
		if p.src[p.pos] == ']' {
			p.pos++
			return node, nil
		}
		return nil, fmt.Errorf("yaml: invalid flow sequence separator")
	}
}

func (p *flowParser) parseQuoted() (*Node, error) {
	start := p.pos
	p.pos++
	escaped := false
	for !p.eof() {
		ch := p.src[p.pos]
		if escaped {
			escaped = false
			p.pos++
			continue
		}
		if ch == '\\' {
			escaped = true
			p.pos++
			continue
		}
		if ch == '"' {
			p.pos++
			value, err := strconv.Unquote(p.src[start:p.pos])
			if err != nil {
				return nil, err
			}
			return &Node{Kind: ScalarNode, Tag: "!!str", Value: value}, nil
		}
		p.pos++
	}
	return nil, fmt.Errorf("yaml: unterminated quoted string")
}

func (p *flowParser) readPlainToken() string {
	start := p.pos
	depth := 0
	for !p.eof() {
		ch := p.src[p.pos]
		switch ch {
		case '{', '[':
			depth++
		case '}', ']':
			if depth == 0 {
				return strings.TrimSpace(p.src[start:p.pos])
			}
			depth--
		case ',':
			if depth == 0 {
				return strings.TrimSpace(p.src[start:p.pos])
			}
		}
		p.pos++
	}
	return strings.TrimSpace(p.src[start:p.pos])
}

func (p *flowParser) readFlowKey() string {
	p.skipSpaces()
	start := p.pos
	if !p.eof() && p.src[p.pos] == '"' {
		node, _ := p.parseQuoted()
		return strconv.Quote(node.Value)
	}
	depth := 0
	for !p.eof() {
		ch := p.src[p.pos]
		if ch == ':' && depth == 0 {
			return strings.TrimSpace(p.src[start:p.pos])
		}
		switch ch {
		case '{', '[':
			depth++
		case '}', ']':
			if depth > 0 {
				depth--
			}
		}
		p.pos++
	}
	return strings.TrimSpace(p.src[start:p.pos])
}

func renderYAML(node *Node, indent int, depth int) string {
	if node == nil {
		return "\n"
	}
	var b strings.Builder
	renderNode(&b, node, indent, depth)
	if !strings.HasSuffix(b.String(), "\n") {
		b.WriteByte('\n')
	}
	return b.String()
}

func renderNode(b *strings.Builder, node *Node, indent int, depth int) {
	switch node.Kind {
	case ScalarNode:
		b.WriteString(renderScalar(node))
	case MappingNode:
		if node.Style&FlowStyle != 0 {
			b.WriteString(renderFlowMap(node))
		} else {
			renderBlockMap(b, node, indent, depth)
		}
	case SequenceNode:
		if node.Style&FlowStyle != 0 {
			b.WriteString(renderFlowSeq(node))
		} else {
			renderBlockSeq(b, node, indent, depth)
		}
	}
}

func renderBlockMap(b *strings.Builder, node *Node, indent int, depth int) {
	for i := 0; i < len(node.Content); i += 2 {
		writeIndent(b, depth, indent)
		b.WriteString(renderKey(node.Content[i].Value))
		value := node.Content[i+1]
		if isInlineNode(value) {
			b.WriteString(": ")
			b.WriteString(renderInline(value))
			b.WriteByte('\n')
		} else {
			b.WriteString(":\n")
			renderNode(b, value, indent, depth+1)
		}
	}
}

func renderBlockSeq(b *strings.Builder, node *Node, indent int, depth int) {
	for _, child := range node.Content {
		writeIndent(b, depth, indent)
		if isInlineNode(child) {
			b.WriteString("- ")
			b.WriteString(renderInline(child))
			b.WriteByte('\n')
			continue
		}
		if child.Kind == MappingNode && child.Style&FlowStyle == 0 && len(child.Content) > 0 {
			b.WriteString("- ")
			b.WriteString(renderKey(child.Content[0].Value))
			firstVal := child.Content[1]
			if isInlineNode(firstVal) {
				b.WriteString(": ")
				b.WriteString(renderInline(firstVal))
				b.WriteByte('\n')
			} else {
				b.WriteString(":\n")
				renderNode(b, firstVal, indent, depth+2)
			}
			for i := 2; i < len(child.Content); i += 2 {
				writeIndent(b, depth+1, indent)
				b.WriteString(renderKey(child.Content[i].Value))
				value := child.Content[i+1]
				if isInlineNode(value) {
					b.WriteString(": ")
					b.WriteString(renderInline(value))
					b.WriteByte('\n')
				} else {
					b.WriteString(":\n")
					renderNode(b, value, indent, depth+2)
				}
			}
			continue
		}
		b.WriteString("-\n")
		renderNode(b, child, indent, depth+1)
	}
}

func renderInline(node *Node) string {
	switch node.Kind {
	case ScalarNode:
		return renderScalar(node)
	case MappingNode:
		return renderFlowMap(node)
	case SequenceNode:
		return renderFlowSeq(node)
	default:
		return "null"
	}
}

func renderFlowMap(node *Node) string {
	parts := make([]string, 0, len(node.Content)/2)
	for i := 0; i < len(node.Content); i += 2 {
		parts = append(parts, renderKey(node.Content[i].Value)+": "+renderInline(node.Content[i+1]))
	}
	return "{" + strings.Join(parts, ", ") + "}"
}

func renderFlowSeq(node *Node) string {
	parts := make([]string, 0, len(node.Content))
	for _, child := range node.Content {
		parts = append(parts, renderInline(child))
	}
	return "[" + strings.Join(parts, ", ") + "]"
}

func renderScalar(node *Node) string {
	switch node.Tag {
	case "!!null":
		return "null"
	case "!!bool", "!!int", "!!float":
		return node.Value
	default:
		if needsQuotes(node.Value) {
			return strconv.Quote(node.Value)
		}
		return node.Value
	}
}

func renderKey(key string) string {
	if needsQuotes(key) {
		return strconv.Quote(key)
	}
	return key
}

func needsQuotes(s string) bool {
	if s == "" {
		return true
	}
	if strings.TrimSpace(s) != s {
		return true
	}
	if strings.ContainsAny(s, "[]{}#,\n\r\t") {
		return true
	}
	if strings.Contains(s, ":") {
		return true
	}
	switch s {
	case "null", "true", "false", "~":
		return true
	}
	return isNumber(s)
}

func isInlineNode(node *Node) bool {
	if node == nil {
		return true
	}
	if node.Kind == ScalarNode {
		return true
	}
	return node.Style&FlowStyle != 0
}

func writeIndent(b *strings.Builder, depth int, indent int) {
	b.WriteString(strings.Repeat(" ", depth*indent))
}

func isNumber(s string) bool {
	if s == "" {
		return false
	}
	if _, err := strconv.ParseInt(s, 10, 64); err == nil {
		return true
	}
	if _, err := strconv.ParseFloat(s, 64); err == nil {
		return true
	}
	return false
}

func newNullNode() *Node {
	return &Node{Kind: ScalarNode, Tag: "!!null", Value: "null"}
}

func cloneNode(node *Node) *Node {
	if node == nil {
		return nil
	}
	copy := *node
	if len(node.Content) > 0 {
		copy.Content = make([]*Node, len(node.Content))
		for i, child := range node.Content {
			copy.Content[i] = cloneNode(child)
		}
	}
	return &copy
}

/workspace/compat.go.content:
package main

import (
	"bytes"
	"encoding/base64"
	"encoding/xml"
	"fmt"
	"io"
	"net/url"
	"os"
	"path/filepath"
	"strconv"
	"strings"
)

func canonicalFormat(raw string) (string, error) {
	switch strings.ToLower(strings.TrimSpace(raw)) {
	case "", "auto", "a":
		return "auto", nil
	case "yaml", "y", "kyaml", "ky":
		return "yaml", nil
	case "json", "j":
		return "json", nil
	case "xml", "x":
		return "xml", nil
	case "props", "p", "properties":
		return "props", nil
	case "shell", "s":
		return "shell", nil
	case "lua", "l":
		return "lua", nil
	case "ini", "i":
		return "ini", nil
	case "base64":
		return "base64", nil
	case "uri":
		return "uri", nil
	case "csv", "c":
		return "csv", nil
	case "tsv", "t":
		return "tsv", nil
	case "toml":
		return "toml", nil
	case "hcl", "h":
		return "hcl", nil
	default:
		return "", fmt.Errorf("unknown format '%s'", raw)
	}
}

func detectInputFormat(path string) string {
	switch strings.ToLower(filepath.Ext(path)) {
	case ".yaml", ".yml":
		return "yaml"
	case ".json":
		return "json"
	case ".xml":
		return "xml"
	case ".properties":
		return "props"
	case ".ini":
		return "ini"
	default:
		return "yaml"
	}
}

func parseDocuments(data []byte, format string, source string) ([]*Value, error) {
	switch format {
	case "", "auto":
		if source != "" && source != "-" {
			format = detectInputFormat(source)
		} else {
			format = "yaml"
		}
	}
	switch format {
	case "yaml":
		return ParseYAMLDocuments(string(data))
	case "json":
		value, err := ParseJSONValue(data)
		if err != nil {
			return nil, err
		}
		return []*Value{value}, nil
	case "xml":
		value, err := parseXMLValue(data)
		if err != nil {
			return nil, err
		}
		return []*Value{value}, nil
	case "props":
		return []*Value{parsePropsValue(data)}, nil
	case "ini":
		return []*Value{parseINIValue(data)}, nil
	case "base64":
		decoded, err := base64.StdEncoding.DecodeString(strings.TrimSpace(string(data)))
		if err != nil {
			return nil, err
		}
		return []*Value{StringValue(string(decoded))}, nil
	case "uri":
		decoded, err := url.QueryUnescape(strings.TrimSpace(string(data)))
		if err != nil {
			return nil, err
		}
		return []*Value{StringValue(decoded)}, nil
	default:
		return nil, fmt.Errorf("unsupported input format: %s", format)
	}
}

func loadSingleValue(path string, inputFormat string) (*Value, error) {
	data, err := os.ReadFile(path)
	if err != nil {
		return nil, err
	}
	format := detectInputFormat(path)
	if format == "yaml" && inputFormat != "" && inputFormat != "auto" {
		format = inputFormat
	}
	values, err := parseDocuments(data, format, path)
	if err != nil {
		return nil, err
	}
	if len(values) == 0 {
		return NullValue(), nil
	}
	if len(values) == 1 {
		return values[0], nil
	}
	return ArrayValue(values), nil
}

func renderValue(v *Value, format string, pretty bool, indent int, unwrapScalar bool, shellKeySep string, propertiesSep string) (string, error) {
	switch format {
	case "", "auto", "yaml":
		return RenderYAMLDocument(v, indent, pretty, unwrapScalar), nil
	case "json":
		var b strings.Builder
		if err := WriteJSON(&b, v, true, 0, indent); err != nil {
			return "", err
		}
		b.WriteByte('\n')
		return b.String(), nil
	case "xml":
		return renderXMLValue(v)
	case "props":
		return renderPropsValue(v, propertiesSep, false), nil
	case "shell":
		return renderShellValue(v, shellKeySep), nil
	case "ini":
		return renderINIValue(v), nil
	case "lua":
		return renderLuaValue(v, "return ", ";\n", false, false), nil
	case "base64":
		return base64.StdEncoding.EncodeToString([]byte(renderScalarAsString(v))) + "\n", nil
	case "uri":
		return url.QueryEscape(renderScalarAsString(v)) + "\n", nil
	default:
		return "", fmt.Errorf("unsupported output format: %s", format)
	}
}

type xmlElem struct {
	Name     string
	Attrs    []xml.Attr
	Children []*xmlElem
	Text     string
}

func parseXMLValue(data []byte) (*Value, error) {
	dec := xml.NewDecoder(bytes.NewReader(data))
	var stack []*xmlElem
	var root *xmlElem
	for {
		tok, err := dec.Token()
		if err == io.EOF {
			break
		}
		if err != nil {
			return nil, err
		}
		switch t := tok.(type) {
		case xml.StartElement:
			elem := &xmlElem{Name: t.Name.Local, Attrs: t.Attr}
			if len(stack) == 0 {
				root = elem
			} else {
				parent := stack[len(stack)-1]
				parent.Children = append(parent.Children, elem)
			}
			stack = append(stack, elem)
		case xml.EndElement:
			if len(stack) > 0 {
				stack = stack[:len(stack)-1]
			}
		case xml.CharData:
			if len(stack) == 0 {
				continue
			}
			text := strings.TrimSpace(string(t))
			if text == "" {
				continue
			}
			cur := stack[len(stack)-1]
			cur.Text += text
		}
	}
	if root == nil {
		return ObjectValue(newObject()), nil
	}
	obj := newObject()
	obj.Set(root.Name, xmlElemToValue(root))
	return ObjectValue(obj), nil
}

func xmlElemToValue(elem *xmlElem) *Value {
	if len(elem.Attrs) == 0 && len(elem.Children) == 0 {
		if elem.Text == "" {
			return StringValue("")
		}
		return StringValue(elem.Text)
	}
	obj := newObject()
	for _, attr := range elem.Attrs {
		obj.Set("+@"+attr.Name.Local, StringValue(attr.Value))
	}
	if elem.Text != "" {
		obj.Set("+content", StringValue(elem.Text))
	}
	grouped := map[string][]*Value{}
	order := []string{}
	for _, child := range elem.Children {
		if _, ok := grouped[child.Name]; !ok {
			order = append(order, child.Name)
		}
		grouped[child.Name] = append(grouped[child.Name], xmlElemToValue(child))
	}
	for _, key := range order {
		values := grouped[key]
		if len(values) == 1 {
			obj.Set(key, values[0])
		} else {
			obj.Set(key, ArrayValue(values))
		}
	}
	return ObjectValue(obj)
}

func parsePropsValue(data []byte) *Value {
	root := newObject()
	for _, line := range strings.Split(string(data), "\n") {
		line = strings.TrimSpace(line)
		if line == "" || strings.HasPrefix(line, "#") || strings.HasPrefix(line, "!") {
			continue
		}
		sep := strings.IndexAny(line, "=:")
		if sep < 0 {
			continue
		}
		key := strings.TrimSpace(line[:sep])
		val := strings.TrimSpace(line[sep+1:])
		assignPathValue(root, strings.Split(key, "."), parseLooseScalar(val))
	}
	return ObjectValue(root)
}

func parseINIValue(data []byte) *Value {
	root := newObject()
	current := root
	for _, line := range strings.Split(string(data), "\n") {
		line = strings.TrimSpace(line)
		if line == "" || strings.HasPrefix(line, ";") || strings.HasPrefix(line, "#") {
			continue
		}
		if strings.HasPrefix(line, "[") && strings.HasSuffix(line, "]") {
			name := strings.TrimSpace(line[1 : len(line)-1])
			section := newObject()
			root.Set(name, ObjectValue(section))
			current = section
			continue
		}
		sep := strings.IndexAny(line, "=:")
		if sep < 0 {
			continue
		}
		key := strings.TrimSpace(line[:sep])
		val := strings.TrimSpace(line[sep+1:])
		current.Set(key, parseLooseScalar(val))
	}
	return ObjectValue(root)
}

func assignPathValue(root *Object, parts []string, value *Value) {
	if len(parts) == 0 {
		return
	}
	current := root
	for i, part := range parts {
		if i == len(parts)-1 {
			current.Set(part, value.Clone())
			return
		}
		next, ok := current.Get(part)
		if !ok || next.Kind != ObjectKind {
			child := newObject()
			current.Set(part, ObjectValue(child))
			current = child
			continue
		}
		current = next.Object
	}
}

func renderXMLValue(v *Value) (string, error) {
	if v == nil {
		return "", fmt.Errorf("xml output requires an object root")
	}
	if v.Kind != ObjectKind {
		return "", fmt.Errorf("xml output requires an object root")
	}
	var buf bytes.Buffer
	for _, pair := range v.Object.Pairs {
		if err := writeXMLNode(&buf, pair.Key, pair.Value, 0); err != nil {
			return "", err
		}
	}
	return buf.String(), nil
}

func writeXMLNode(buf *bytes.Buffer, name string, v *Value, depth int) error {
	indent := strings.Repeat("  ", depth)
	switch {
	case v.Kind == ArrayKind:
		for _, item := range v.Array {
			if err := writeXMLNode(buf, name, item, depth); err != nil {
				return err
			}
		}
		return nil
	case v.Kind == ObjectKind:
		attrs := []Pair{}
		children := []Pair{}
		text := ""
		for _, pair := range v.Object.Pairs {
			switch {
			case strings.HasPrefix(pair.Key, "+@"):
				attrs = append(attrs, pair)
			case pair.Key == "+content":
				text = renderScalarAsString(pair.Value)
			default:
				children = append(children, pair)
			}
		}
		buf.WriteString(indent)
		buf.WriteByte('<')
		buf.WriteString(name)
		for _, attr := range attrs {
			buf.WriteByte(' ')
			buf.WriteString(strings.TrimPrefix(attr.Key, "+@"))
			buf.WriteString(`="`)
			xml.EscapeText(buf, []byte(renderScalarAsString(attr.Value)))
			buf.WriteByte('"')
		}
		if text == "" && len(children) == 0 {
			buf.WriteString("></")
			buf.WriteString(name)
			buf.WriteString(">\n")
			return nil
		}
		if len(children) == 0 {
			buf.WriteByte('>')
			xml.EscapeText(buf, []byte(text))
			buf.WriteString("</")
			buf.WriteString(name)
			buf.WriteString(">\n")
			return nil
		}
		buf.WriteString(">\n")
		if text != "" {
			buf.WriteString(strings.Repeat("  ", depth+1))
			xml.EscapeText(buf, []byte(text))
			buf.WriteByte('\n')
		}
		for _, child := range children {
			if err := writeXMLNode(buf, child.Key, child.Value, depth+1); err != nil {
				return err
			}
		}
		buf.WriteString(indent)
		buf.WriteString("</")
		buf.WriteString(name)
		buf.WriteString(">\n")
		return nil
	default:
		buf.WriteString(indent)
		buf.WriteByte('<')
		buf.WriteString(name)
		buf.WriteByte('>')
		xml.EscapeText(buf, []byte(renderScalarAsString(v)))
		buf.WriteString("</")
		buf.WriteString(name)
		buf.WriteString(">\n")
		return nil
	}
}

type flatLine struct {
	Key   string
	Value string
}

func renderPropsValue(v *Value, sep string, arrayBrackets bool) string {
	if sep == "" {
		sep = " = "
	}
	lines := flattenValue(v, "", ".", arrayBrackets)
	var b strings.Builder
	for i, line := range lines {
		if i > 0 {
			b.WriteByte('\n')
		}
		b.WriteString(line.Key)
		b.WriteString(sep)
		b.WriteString(line.Value)
	}
	if b.Len() > 0 {
		b.WriteByte('\n')
	}
	return b.String()
}

func renderShellValue(v *Value, sep string) string {
	if sep == "" {
		sep = "_"
	}
	lines := flattenValue(v, "", sep, false)
	var b strings.Builder
	for i, line := range lines {
		if i > 0 {
			b.WriteByte('\n')
		}
		b.WriteString(line.Key)
		b.WriteByte('=')
		b.WriteString(shellEscape(line.Value))
	}
	if b.Len() > 0 {
		b.WriteByte('\n')
	}
	return b.String()
}

func renderINIValue(v *Value) string {
	if v == nil || v.Kind != ObjectKind {
		return ""
	}
	var b strings.Builder
	first := true
	for _, pair := range v.Object.Pairs {
		if pair.Value.Kind != ObjectKind {
			continue
		}
		if !first {
			b.WriteByte('\n')
		}
		first = false
		b.WriteString("[")
		b.WriteString(pair.Key)
		b.WriteString("]\n")
		for _, entry := range pair.Value.Object.Pairs {
			if !isScalar(entry.Value) {
				continue
			}
			b.WriteString(entry.Key)
			b.WriteString(" = ")
			b.WriteString(renderScalarAsString(entry.Value))
			b.WriteByte('\n')
		}
	}
	return b.String()
}

func renderLuaValue(v *Value, prefix, suffix string, unquoted, globals bool) string {
	if prefix == "" {
		prefix = "return "
	}
	if suffix == "" {
		suffix = ";\n"
	}
	if globals && v != nil && v.Kind == ObjectKind {
		var b strings.Builder
		for _, pair := range v.Object.Pairs {
			b.WriteString(luaKey(pair.Key, unquoted))
			b.WriteString(" = ")
			b.WriteString(luaValue(pair.Value, 0, unquoted))
			b.WriteString(suffix)
		}
		return b.String()
	}
	return prefix + luaValue(v, 0, unquoted) + suffix
}

func luaValue(v *Value, depth int, unquoted bool) string {
	if v == nil {
		return "nil"
	}
	indent := strings.Repeat("\t", depth)
	childIndent := strings.Repeat("\t", depth+1)
	switch v.Kind {
	case NullKind:
		return "nil"
	case BoolKind:
		if v.Bool {
			return "true"
		}
		return "false"
	case NumberKind:
		return v.Number
	case StringKind:
		return strconv.Quote(v.String)
	case ArrayKind:
		if len(v.Array) == 0 {
			return "{}"
		}
		var b strings.Builder
		b.WriteString("{\n")
		for _, item := range v.Array {
			b.WriteString(childIndent)
			b.WriteString(luaValue(item, depth+1, unquoted))
			b.WriteString(",\n")
		}
		b.WriteString(indent)
		b.WriteString("}")
		return b.String()
	case ObjectKind:
		if len(v.Object.Pairs) == 0 {
			return "{}"
		}
		var b strings.Builder
		b.WriteString("{\n")
		for _, pair := range v.Object.Pairs {
			b.WriteString(childIndent)
			b.WriteString(luaKey(pair.Key, unquoted))
			b.WriteString(" = ")
			b.WriteString(luaValue(pair.Value, depth+1, unquoted))
			b.WriteString(";\n")
		}
		b.WriteString(indent)
		b.WriteString("}")
		return b.String()
	default:
		return "nil"
	}
}

func luaKey(key string, unquoted bool) string {
	if unquoted && isLuaIdentifier(key) {
		return key
	}
	return "[" + strconv.Quote(key) + "]"
}

func isLuaIdentifier(s string) bool {
	if s == "" {
		return false
	}
	for i, r := range s {
		if i == 0 {
			if !(r == '_' || ('A' <= r && r <= 'Z') || ('a' <= r && r <= 'z')) {
				return false
			}
			continue
		}
		if !(r == '_' || ('A' <= r && r <= 'Z') || ('a' <= r && r <= 'z') || ('0' <= r && r <= '9')) {
			return false
		}
	}
	return true
}

func flattenValue(v *Value, prefix, sep string, arrayBrackets bool) []flatLine {
	if v == nil {
		return []flatLine{{Key: prefix, Value: "null"}}
	}
	switch v.Kind {
	case ObjectKind:
		var out []flatLine
		for _, pair := range v.Object.Pairs {
			key := pair.Key
			if prefix != "" {
				key = prefix + sep + key
			}
			out = append(out, flattenValue(pair.Value, key, sep, arrayBrackets)...)
		}
		return out
	case ArrayKind:
		var out []flatLine
		for i, item := range v.Array {
			key := strconv.Itoa(i)
			if prefix != "" {
				if arrayBrackets {
					key = fmt.Sprintf("%s[%d]", prefix, i)
				} else {
					key = fmt.Sprintf("%s%s%d", prefix, sep, i)
				}
			}
			out = append(out, flattenValue(item, key, sep, arrayBrackets)...)
		}
		return out
	default:
		return []flatLine{{Key: prefix, Value: renderScalarAsString(v)}}
	}
}

func renderScalarAsString(v *Value) string {
	if v == nil {
		return "null"
	}
	switch v.Kind {
	case NullKind:
