func parseYAMLDocuments(data []byte) ([]Value, error) {
	dec := yaml.NewDecoder(bytes.NewReader(data))
	var docs []Value
	for {
		var node yaml.Node
		err := dec.Decode(&node)
		if err == io.EOF {
			break
		}
		if err != nil {
			return nil, err
		}
		if len(node.Content) == 0 {
			docs = append(docs, nil)
			continue
		}
		docs = append(docs, yamlNodeToValue(node.Content[0]))
	}
	return docs, nil
}

func yamlNodeToValue(node *yaml.Node) Value {
	switch node.Kind {
	case yaml.DocumentNode:
		if len(node.Content) == 0 {
			return nil
		}
		return yamlNodeToValue(node.Content[0])
	case yaml.MappingNode:
		obj := &OrderedMap{}
		for i := 0; i+1 < len(node.Content); i += 2 {
			key := node.Content[i].Value
			obj.Entries = append(obj.Entries, Entry{Key: key, Value: yamlNodeToValue(node.Content[i+1])})
		}
		return obj
	case yaml.SequenceNode:
		out := make([]Value, 0, len(node.Content))
		for _, child := range node.Content {
			out = append(out, yamlNodeToValue(child))
		}
		return out
	case yaml.ScalarNode:
		switch node.Tag {
		case "!!null":
			return nil
		case "!!bool":
			return strings.EqualFold(node.Value, "true")
		case "!!int":
			if v, err := strconv.ParseInt(node.Value, 10, 64); err == nil {
				return v
			}
		case "!!float":
			if v, err := strconv.ParseFloat(node.Value, 64); err == nil {
				return v
			}
		}
		return node.Value
	default:
		return nil
	}
}

func parseJSONBytes(data []byte) (Value, error) {
	dec := json.NewDecoder(bytes.NewReader(data))
	dec.UseNumber()
	val, err := parseJSONValue(dec)
	if err != nil {
		return nil, err
	}
	return val, nil
}

func parseJSONValue(dec *json.Decoder) (Value, error) {
	tok, err := dec.Token()
	if err != nil {
