package yaml

import (
	"bufio"
	"bytes"
	"fmt"
	"io"
	"strconv"
	"strings"
)

type Kind uint32
type Style uint32

const (
	DocumentNode Kind = 1 + iota
	SequenceNode
	MappingNode
	ScalarNode
)

const (
	FlowStyle Style = 1 << iota
)

type Node struct {
	Kind    Kind
	Style   Style
	Tag     string
	Value   string
	Content []*Node
}

type Decoder struct {
	data   []byte
	docs   []*Node
	err    error
	parsed bool
	index  int
}

func NewDecoder(r io.Reader) *Decoder {
	data, err := io.ReadAll(r)
	return &Decoder{data: data, err: err}
}

func (d *Decoder) Decode(v any) error {
	if d.err != nil {
		return d.err
	}
	if !d.parsed {
		d.docs, d.err = parseDocuments(d.data)
		d.parsed = true
		if d.err != nil {
			return d.err
		}
	}
	if d.index >= len(d.docs) {
		return io.EOF
	}
	target, ok := v.(*Node)
	if !ok {
		return fmt.Errorf("yaml: Decode expects *Node")
	}
	*target = Node{Kind: DocumentNode}
	if d.docs[d.index] != nil {
		target.Content = []*Node{cloneNode(d.docs[d.index])}
	}
	d.index++
	return nil
}

type Encoder struct {
	w      io.Writer
	indent int
}

func NewEncoder(w io.Writer) *Encoder {
	return &Encoder{w: w, indent: 2}
}

func (e *Encoder) SetIndent(n int) {
	e.indent = n
}

func (e *Encoder) Encode(v any) error {
	var node *Node
	switch t := v.(type) {
	case *Node:
		node = t
	case Node:
		node = &t
	default:
		return fmt.Errorf("yaml: Encode expects Node")
	}
	if node.Kind == DocumentNode {
		if len(node.Content) == 0 || node.Content[0] == nil {
			_, err := io.WriteString(e.w, "\n")
			return err
		}
		_, err := io.WriteString(e.w, renderYAML(node.Content[0], e.indent, 0))
		return err
	}
	_, err := io.WriteString(e.w, renderYAML(node, e.indent, 0))
	return err
}

func (e *Encoder) Close() error {
	return nil
}

func parseDocuments(data []byte) ([]*Node, error) {
	if len(data) == 0 {
		return []*Node{nil}, nil
	}
	scanner := bufio.NewScanner(bytes.NewReader(data))
	docs := make([][]string, 1)
	for scanner.Scan() {
		line := strings.TrimRight(scanner.Text(), "\r")
		if strings.TrimSpace(line) == "---" {
			docs = append(docs, nil)
			continue
		}
		docs[len(docs)-1] = append(docs[len(docs)-1], line)
	}
	if err := scanner.Err(); err != nil {
		return nil, err
	}
	out := make([]*Node, 0, len(docs))
	for _, docLines := range docs {
		node, err := parseDocument(docLines)
		if err != nil {
			return nil, err
		}
		out = append(out, node)
	}
	return out, nil
}

type parsedLine struct {
	indent int
	text   string
}

func parseDocument(lines []string) (*Node, error) {
	parsed := make([]parsedLine, 0, len(lines))
	for _, raw := range lines {
		if strings.TrimSpace(raw) == "" {
			continue
		}
		trimmed := strings.TrimLeft(raw, " ")
		if strings.HasPrefix(trimmed, "#") {
			continue
		}
		indent := len(raw) - len(trimmed)
		parsed = append(parsed, parsedLine{indent: indent, text: trimmed})
	}
	if len(parsed) == 0 {
		return nil, nil
	}
	index := 0
	return parseBlock(parsed, &index, parsed[0].indent)
}

func parseBlock(lines []parsedLine, index *int, indent int) (*Node, error) {
	if *index >= len(lines) {
		return nil, nil
	}
	line := lines[*index]
	if line.indent < indent {
		return nil, nil
	}
	if line.indent > indent {
		return nil, fmt.Errorf("yaml: unexpected indentation")
	}
	if strings.HasPrefix(line.text, "- ") || line.text == "-" {
		return parseSequence(lines, index, indent)
	}
	if _, _, ok := splitKeyValue(line.text); ok {
		return parseMapping(lines, index, indent)
	}
	*index++
	return parseInlineValue(line.text)
}

func parseSequence(lines []parsedLine, index *int, indent int) (*Node, error) {
	seq := &Node{Kind: SequenceNode, Tag: "!!seq"}
